/**
 * Column fragments every Taskflow table reuses.
 *
 * Conventions enforced here:
 *  - ids are ULID text primary keys
 *  - timestamps are ISO-8601 text, not unix integers
 *  - every tenant-scoped table carries `org_id`
 *  - every soft-deletable table carries `archived_at`
 */

export const nowIso = () => new Date().toISOString();

export const idColumn = (name = "id") => text(name).primaryKey();

export const timestampColumns = {
  createdAt: text("created_at").notNull().$defaultFn(nowIso),
  updatedAt: text("updated_at").notNull().$defaultFn(nowIso),
};

/** Spread into every table that belongs to exactly one organization. */
export const tenantColumns = {
  orgId: text("org_id").notNull(),
};

/** Spread into every table that is archived rather than deleted. */
export const softDeleteColumns = {
  archivedAt: text("archived_at"),
};

/**
 * The `organization_usage` counters read by every plan-limit check.
 */
import { and, count, eq, isNull, sql } from "drizzle-orm";
import {
  attachments,
  getDb,
  issues,
  members,
  organizationUsage,
  projects,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUsage } from "./_mappers";
import { brandId } from "./_mappers";
import type { OrgId } from "@/types/common";
import type { OrganizationUsage } from "@/types/organization";

const BYTES_PER_MB = 1024 * 1024;

/**
 * Reads the cached counters, materialising a zeroed row the first time an org
 * is asked about. A limit check must never fail because the rollup has not run.
 */
export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
  const row = getDb()
    .select()
    .from(organizationUsage)
    .where(eq(organizationUsage.orgId, orgId))
    .get();

  if (row) return toUsage(row);

  const created = getDb()
    .insert(organizationUsage)
    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
    .returning()
    .get();

  return toUsage(created);
}

/**
 * Recounts every dimension from the source tables and rewrites the cache.
 * Called by the rollup job and after any bulk change that would drift.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const db = getDb();

  const seats = db
    .select({ value: count() })
    .from(members)
    .where(
      and(
        eq(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .get();

  const projectCount = db
    .select({ value: count() })
    .from(projects)
    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
    .get();

  const issueCount = db
    .select({ value: count() })
    .from(issues)
    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
    .get();

  const bytes = db
    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
    .from(attachments)
    .where(eq(attachments.orgId, orgId))
    .get();

  const next = {
    orgId,
    seatsUsed: seats?.value ?? 0,
    projectsUsed: projectCount?.value ?? 0,
    issuesUsed: issueCount?.value ?? 0,
    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
    measuredAt: toIsoTimestamp(new Date()),
  };

  const row = db
    .insert(organizationUsage)
    .values(next)
    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
    .returning()
    .get();

  return toUsage(row);
}

/**
 * Cheap delta applied on the write path so a quota check right after a create
 * sees the new number without waiting for the rollup.
 */
export async function incrementUsage(
  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
      projectsUsed: current.projectsUsed + (patch.projectsUsed ?? 0),
      issuesUsed: current.issuesUsed + (patch.issuesUsed ?? 0),
      storageMbUsed: current.storageMbUsed + (patch.storageMbUsed ?? 0),
      measuredAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

/** The rollup job's work list: the oldest measurements first. */
export async function listOrgIdsForRollup(
  limit: number,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ orgId: organizationUsage.orgId })
    .from(organizationUsage)
    .orderBy(organizationUsage.measuredAt)
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => brandId<OrgId>(row.orgId));
}

/**
 * Data-layer entry point. Repositories import `{ getDb }` and the table
 * objects from here so the concrete client module stays swappable.
 */
export { getDb, useInMemoryDb } from "./client";
export type { Db, DbSchema } from "./client";
export * from "./schema";

import { mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import * as schema from "./schema";

/**
 * The single Drizzle connection for the process.
 *
 * Repositories import `db` from `@/server/db` (the barrel), never this module
 * directly, so the connection can be swapped in tests. Never construct a
 * second `Database` — SQLite in WAL mode tolerates it, but the in-process
 * event bus assumes one writer.
 */

const DEFAULT_DB_PATH = "./data/taskflow.db";

let instance: ReturnType<typeof createClient> | null = null;

function createClient(path: string) {
  const absolute = resolve(process.cwd(), path);
  mkdirSync(dirname(absolute), { recursive: true });
  const sqlite = new Database(absolute);
  sqlite.pragma("journal_mode = WAL");
  sqlite.pragma("foreign_keys = ON");
  return drizzle(sqlite, { schema });
}

export function getDb(path: string = process.env.TASKFLOW_DB_PATH ?? DEFAULT_DB_PATH) {
  instance ??= createClient(path);
  return instance;
}

/** Test hook: point the singleton at an in-memory database. */
export function useInMemoryDb(): void {
  instance = createClient(":memory:");
}

export type Db = ReturnType<typeof getDb>;
export type DbSchema = typeof schema;

/**
 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
 *
 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
 */
import { subscribe } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { enqueue } from "@/server/jobs/queue";
import { toIsoTimestamp } from "@/types/common";
import { registerActivityListeners } from "./activity-service";
import { registerSearchListeners } from "./search-service";
import { registerUsageListeners } from "./usage-service";
import { registerWebhookListeners } from "./webhook-service";
import type { Unsubscribe } from "@/types/event";

/**
 * Importing this module also loads `notification-service` transitively, which
 * attaches the notification fan-out on first import — that hub has no
 * `register*` entry point of its own.
 */
import "./notification-service";

const logger = createLogger("event-registry");

/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
let detach: Unsubscribe | null = null;

/**
 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
 * runs per server process, but a hot reload in dev can call it again and must
 * not double-deliver every event.
 */
export function registerEventHandlers(): void {
  if (detach !== null) return;

  const offs: Unsubscribe[] = [
    registerActivityListeners(),
    registerSearchListeners(),
    registerUsageListeners(),
    registerWebhookListeners(),
    registerDigestBridge(),
  ];

  detach = () => {
    for (const off of offs) off();
  };

  logger.info("event handlers registered", { groups: offs.length });
}

export function unregisterEventHandlers(): void {
  detach?.();
  detach = null;
}

/**
 * The one piece of wiring that belongs to no single service: turning a
 * `digest.due` event into a queued job. Keeping it here rather than inside
 * `DigestService` stops the service layer from depending on the job layer.
 */
function registerDigestBridge(): Unsubscribe {
  return subscribe("digest.due", (payload) => {
    enqueue({
      id: `digest:${payload.orgId}:${payload.recipientId}`,
      kind: "digest-email",
      runAt: toIsoTimestamp(new Date()),
      attempts: 0,
      payload: {
        orgId: payload.orgId,
        recipientId: payload.recipientId,
        windowStart: payload.windowStart,
      },
    });
  });
}

/**
 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
 *
 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
 */
import { isEnabled } from "@/lib/feature-flags";
import { createLogger } from "@/lib/logger";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
import { sendEmail } from "@/server/services/email-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Organization } from "@/types/organization";

const ORG_BATCH = 50;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("digest-email-job");

/**
 * One pass per scheduler tick. Each org is only processed during the UTC hour
 * it configured, so a tick that runs every few minutes still sends exactly one
 * digest per day per recipient.
 */
export async function runDigestEmailJob(now: Date): Promise<JobResult> {
  return runJob("digest-email", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org || !shouldRunForOrg(org, now)) continue;

      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;

      const windowEnd = toIsoTimestamp(now);
      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));

      for (const recipientId of await listDigestRecipients(orgId)) {
        try {
          const bundle = await buildDigest(
            orgId,
            recipientId,
            windowStart,
            windowEnd,
          );
          if (!bundle) continue;

          const recipient = await userRepo.findUserById(recipientId);
          if (!recipient) continue;

          const rendered = await renderDigest(bundle, recipient);
          await sendEmail({ to: recipient.email, ...rendered });

          // Once digested, these notifications are no longer "unread" — this
          // is what keeps a later run inside the same window from sending
          // the same digest twice.
          for (const entry of bundle.entries) {
            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
          }

          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("digest failed", {
            orgId,
            recipientId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}

/**
 * True during the org's configured digest hour. Exported because the schedule
 * decision is worth testing on its own, without a database.
 */
export function shouldRunForOrg(org: Organization, now: Date): boolean {
  if (org.archivedAt !== null) return false;
  return now.getUTCHours() === org.settings.digestHourUtc;
}

import type {
  EventHandler,
  TaskflowEventMap,
  TaskflowEventPayload,
  TaskflowEventType,
  Unsubscribe,
} from "@/types/event";

/**
 * In-process, typed publish/subscribe bus.
 *
 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
 * every reactive concern `subscribe()`s at module init (see
 * `src/server/services/event-registry.ts`). Handlers are isolated — one
 * throwing handler never fails the emit or the sibling handlers.
 */

type HandlerSet = Set<EventHandler<TaskflowEventType>>;

const handlers = new Map<TaskflowEventType, HandlerSet>();

const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();

/** Registers a handler for one event type. Call the return value to detach. */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set = handlers.get(type) ?? new Set();
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

/** Registers a handler that detaches itself after the first delivery. */
export function subscribeOnce<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const off = subscribe(type, (payload) => {
    off();
    return handler(payload);
  });
  return off;
}

/**
 * Publishes an event to every subscriber. Resolves once all handlers settle;
 * rejected handlers are reported to the error sinks, never rethrown.
 */
export async function emit<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): Promise<void> {
  const set = handlers.get(type);
  if (!set || set.size === 0) return;

  const results = await Promise.allSettled(
    [...set].map(async (handler) => {
      await (handler as EventHandler<K>)(payload);
    }),
  );

  for (const result of results) {
    if (result.status === "rejected") {
      reportHandlerError(type, result.reason);
    }
  }
}

/** Fire-and-forget variant for call sites that must not await delivery. */
export function emitAndForget<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): void {
  void emit(type, payload).catch((error: unknown) => {
    reportHandlerError(type, error);
  });
}

export function onHandlerError(
  sink: (type: TaskflowEventType, error: unknown) => void,
): Unsubscribe {
  errorSinks.add(sink);
  return () => {
    errorSinks.delete(sink);
  };
}

function reportHandlerError(type: TaskflowEventType, error: unknown): void {
  for (const sink of errorSinks) {
    try {
      sink(type, error);
    } catch {
      // A failing error sink must never escalate.
    }
  }
}

/** Number of live subscribers for an event; used by tests and diagnostics. */
export function subscriberCount(type: TaskflowEventType): number {
  return handlers.get(type)?.size ?? 0;
}

/** Detaches every handler. Test-only — never call from application code. */
export function resetEventBus(): void {
  handlers.clear();
  errorSinks.clear();
}

export type { TaskflowEventMap, TaskflowEventType, Unsubscribe };

"use server";

/**
 * Soft-deletes an organization after slug confirmation.
 *
 * Owner D. `confirmSlug` is the "type the name to continue" guard; it is
 * compared against the stored slug rather than trusted, so a stale form cannot
 * delete a renamed organization.
 *
 * Must call (do not reimplement): deleteOrganizationSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  deleteOrganizationSchema,
  type DeleteOrganizationInput,
} from "@/schemas/organization";
import { deleteOrganization } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Organization } from "@/types/organization";
import { revalidatePath } from "next/cache";

const run = withAction<typeof deleteOrganizationSchema, Organization>(
  deleteOrganizationSchema,
  async (raw, actor) => {
    const input = raw as DeleteOrganizationInput;

    if (!can(actor, "org:delete", { kind: "organization", orgId: input.orgId })) {
      throw new ForbiddenActionError("org:delete");
    }

    const organization = await deleteOrganization(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    revalidatePath("/orgs");
    return organization;
  },
  { revalidate: ["organization"], cacheProfile: "minutes" },
);

export async function deleteOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  return run(raw);
}

"use server";

/**
 * Invites one member; enforces the seat quota and the invite rate limit.
 *
 * Owner D. Pending invitations count against `seats` — otherwise an org on the
 * free plan could queue fifty invitations and blow past three seats the moment
 * they are accepted.
 *
 * Must call (do not reimplement): inviteMemberSchema, can, getPlanLimits,
 * consumeRateLimit, getActor, toActionResult
 */

import {
  ForbiddenActionError,
  PlanLimitError,
  RateLimitedError,
} from "@/actions/_lib/action-errors";
import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { inviteMemberSchema, type InviteMemberInput } from "@/schemas/member";
import { inviteMember } from "@/server/services/invitation-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Invitation } from "@/types/member";

const INVITE_BUCKET = "member:invite";

const run = withAction<typeof inviteMemberSchema, Invitation>(
  inviteMemberSchema,
  async (raw, actor) => {
    const input = raw as InviteMemberInput;

    const allowed = can(actor, "member:invite", {
      kind: "member",
      orgId: input.orgId,
      memberId: PENDING_MEMBER_ID,
      targetUserId: actor.userId,
      targetRole: input.role,
    });
    if (!allowed) {
      throw new ForbiddenActionError("member:invite");
    }

    const verdict = await consumeRateLimit(input.orgId, INVITE_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(INVITE_BUCKET, verdict.resetAt);
    }

    const summary = await getOrganizationSummary(actor, input.orgId);
    const limits = getPlanLimits(summary.organization.plan);
    if (summary.usage.seatsUsed + 1 > limits.seats) {
      throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
    }

    const invitation = await inviteMember(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return invitation;
  },
  { revalidate: ["members", "invitations"], cacheProfile: "minutes" },
);

export async function inviteMemberAction(raw: unknown): Promise<ActionResult<Invitation>> {
  return run(raw);
}

/**
 * Credential login, registration and password reset. No third-party provider.
 *
 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
 *
 * Note: `TaskflowEventMap` has no authentication event and the type is part of
 * the frozen contract, so the declared `emit` is not reachable from here.
 * Registration still publishes `member.joined` — through
 * `OrganizationService.createOrganization`, which owns that membership row.
 */
import {
  hashPassword,
  hashToken,
  randomToken,
  verifyPassword,
} from "@/lib/hash";
import { consumeRateLimit } from "@/lib/rate-limit";
import { slugify } from "@/lib/slug";
import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import { createOrganization } from "./organization-service";
import { renderEmail, sendEmail } from "./email-service";
import { createSessionToken } from "./session-service";
import type {
  LoginInput,
  PasswordResetConfirmInput,
  PasswordResetRequestInput,
  RegisterInput,
} from "@/schemas/auth";
import type { OrgId, SessionId } from "@/types/common";
import type { User } from "@/types/member";
import type { Organization } from "@/types/organization";

/** Buckets guarding the unauthenticated endpoints. */
const LOGIN_BUCKET = "auth:login";
const RESET_BUCKET = "auth:password-reset";

/**
 * Rate limiting before a session exists has no tenant to charge against, so
 * every unauthenticated attempt is billed to this sentinel bucket.
 */
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/** How long a password-reset link stays usable. */
const RESET_TTL_MS = 60 * 60 * 1000;

/**
 * Registration creates the user and their first workspace in one step — a
 * Taskflow account with no organization cannot do anything, so there is no
 * intermediate state where one exists without the other.
 */
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const existing = await userRepo.findUserByEmail(input.email);
  if (existing) {
    throw new Error("An account with that email already exists");
  }

  const user = await userRepo.insertUser({
    email: input.email,
    name: input.name,
    passwordHash: await hashPassword(input.password),
  });

  const org = await createOrganization(user.id, {
    name: `${input.name}'s workspace`,
    slug: slugify(input.name) || "workspace",
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

/**
 * Credential login. The rate limit is charged before the password is checked,
 * so a brute-force run is throttled whether or not it guesses correctly, and
 * both failure modes return the same message.
 */
export async function login(
  input: LoginInput,
): Promise<{ user: User; token: string }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
  if (!verdict.allowed) {
    throw new Error("Too many sign-in attempts; try again shortly");
  }

  const user = await userRepo.findUserByEmail(input.email);
  if (!user) throw new Error("Those credentials did not match");

  const storedHash = await userRepo.findPasswordHash(user.id);
  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
    throw new Error("Those credentials did not match");
  }

  const { token } = await createSessionToken(user.id);

  return { user, token };
}

export async function logout(sessionId: SessionId): Promise<void> {
  await sessionRepo.revokeSession(sessionId);
}

/**
 * Always resolves, whether or not the address is known — telling an anonymous
 * caller which emails have accounts is an enumeration oracle. Only the token's
 * hash is stored; the raw value exists solely inside the email that carries it.
 */
export async function requestPasswordReset(
  input: PasswordResetRequestInput,
): Promise<void> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
  if (!verdict.allowed) return;

  const user = await userRepo.findUserByEmail(input.email);
  if (!user) return;

  const token = randomToken(32);
  await resetTokenRepo.issueResetToken(
    user.id,
    hashToken(token),
    toIsoTimestamp(new Date(Date.now() + RESET_TTL_MS)),
  );

  const message = await renderEmail("password-reset", {
    recipientName: user.name,
    token,
    expiresInMinutes: RESET_TTL_MS / 60_000,
  });

  await sendEmail({ to: user.email, ...message });
}

/**
 * Consumes a reset token and rewrites the password hash. The token is marked
 * used before the new hash is written, so a replay of the same link cannot
 * overwrite a password the user has since changed again.
 */
export async function confirmPasswordReset(
  input: PasswordResetConfirmInput,
): Promise<User> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
  if (!verdict.allowed) {
    throw new Error("Too many reset attempts; try again shortly");
  }

  const stored = await resetTokenRepo.findLiveResetToken(
    hashToken(input.token),
  );
  if (!stored) throw new Error("That reset link is no longer valid");

  await resetTokenRepo.consumeResetToken(stored.id);
  await userRepo.updatePasswordHash(
    stored.userId,
    await hashPassword(input.password),
  );

  const user = await userRepo.findUserById(stored.userId);
  if (!user) throw new Error("That reset link is no longer valid");

  return user;
}

