  const at = toIsoTimestamp(new Date());
  const former = await memberRepo.findMemberByEmail(invitation.orgId, email);
  const archived = former ?? await memberRepo.findArchivedMemberByEmail(invitation.orgId, email);
  const member = archived
    ? await memberRepo.restoreMember(invitation.orgId, archived.id, invitation.role, invitation.invitedBy, at)
    : await memberRepo.insertMember(invitation.orgId, userId, invitation.role, invitation.invitedBy);

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    at,
  );

  await usageRepo.recomputeUsage(invitation.orgId);

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

